from typing import TypedDict


class ReviewState(TypedDict):

    # GitHub Pull Request URL
    pr_url: str

    # Original source code fetched from GitHub
    code_contents: dict

    # Errors identified by the linter
    lint_errors: list

    # Refactored code generated by LLM
    refactored_code: dict

    # Human approval status
    is_approved: bool

    # Feedback provided by reviewer
    reviewer_feedback: str

    # History of previous review iterations
    history: list